WITH gaps AS (SELECT *, CASE WHEN event_time - LAG(event_time) OVER (PARTITION BY event_type ORDER BY event_time, id) > INTERVAL '60' DAY THEN 1 ELSE 0 END AS session_start_flag FROM web_events), sessions_web_events AS (SELECT id, session_id, event_type, page, event_time, SUM(session_start_flag) OVER (PARTITION BY event_type ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps), cleaned AS (SELECT id, session_id, page, event_time, island_id, WEEKOFYEAR(event_time) AS event_time_weekofyear, COALESCE(page, 'OTHER') AS page_filled FROM sessions_web_events WHERE HOUR(event_time) BETWEEN 10 AND 13), deduped AS (SELECT * FROM cleaned QUALIFY ROW_NUMBER() OVER (PARTITION BY page ORDER BY island_id DESC, id) = 1), gaps_2 AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) + INTERVAL 90 DAYS THEN 1 ELSE 0 END AS is_new_session FROM deduped), islands AS (SELECT id, session_id, event_time, island_id, SUM(is_new_session) OVER (PARTITION BY session_id ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id_2 FROM gaps_2), deduped_web_events AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY event_time NULLS LAST, id) AS latest_rank FROM islands) ranked WHERE latest_rank = 1) SELECT s.id, s.session_id, s.event_time, s.island_id_2, s.latest_rank, (SELECT MIN(t2.duration_sec) FROM web_events t2 WHERE t2.session_id = s.session_id) AS min_web_event_duration_sec FROM deduped_web_events s ORDER BY latest_rank DESC, id
